    static let byAgency: [String: [SourceLink]] = [
        "AKDN": [Src.akdnWho],
        "AKF": [Src.akfUSA, Src.wikiGBAO],
        "AKHS": [Src.akhs],
        "AKU": [Src.akuBrochure],
        "AKES": [Src.akes],
        "UCA": [Src.wikiUCA],
        "AKAH": [Src.akah],
        "AKTC": [Src.wikiHistoricCities],
        "AKFED": [Src.wikiAKFED, Src.nationMedia]
    ]

    /// Every source in the app, de-duplicated, for the About screen.
    static var all: [SourceLink] {
        var seen = Set<String>()
        let lists: [[SourceLink]] = Array(byChapter.values) + [imams, journey, people, impact, contributions, faithScience, compare]
            + GuideData.all.map(\.sources)
        return lists.flatMap { $0 }
            .filter { seen.insert($0.url).inserted }
            .sorted { $0.title < $1.title }
    }
